import blurManifest from "@/content/blur.json";

type BlurMap = Record<string, string>;
const blurs = blurManifest as BlurMap;

interface MediaInput {
  src: string;
  alt: string;
  width: number;
  height: number;
  kind?: "image" | "video";
  poster?: string;
}

/**
 * Build a Media object, attaching the precomputed blur placeholder when present.
 * Blur placeholders are generated by scripts/gen-blur.mjs into src/content/blur.json.
 */
export function m(input: MediaInput) {
  const kind = input.kind ?? "image";
  return {
    ...input,
    kind,
    blurDataURL: blurs[input.src.replace(/^\//, "")],
  };
}
